example_item.example_item_data:
% Les ondes et le QT median d'un enregistrement simule.
recording = ecglab.simulate('Seconds', 30, 'Rate', 500, 'Seed', 1);
waves = ecglab.delineate(recording);
median(waves.intervals.qt, 'omitnan')

% Douze derivations delimitees et fusionnees ; le debut du QRS global est le plus precoce.
recording = ecglab.simulate('Seconds', 20, 'Rate', 500, 'Leads', 12, 'Seed', 2);
waves = ecglab.delineate(recording, 'Lead', 'all');
numel(waves.perLead)
